package com.northstar.crm.domain;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="plan_definition") public class PlanDefinition extends BaseEntity {@Column(nullable=false,unique=true,length=50)private String name;@Column(nullable=false,precision=12,scale=2)private BigDecimal monthlyPrice;@Column(nullable=false,length=3)private String currency;@Column(nullable=false)private int apiRateLimit;@Column(nullable=false)private int userLimit;protected PlanDefinition(){}public PlanDefinition(String n,BigDecimal p,String c,int rate,int users){name=n;monthlyPrice=p;currency=c;apiRateLimit=rate;userLimit=users;}public String getName(){return name;}public BigDecimal getMonthlyPrice(){return monthlyPrice;}public String getCurrency(){return currency;}public int getApiRateLimit(){return apiRateLimit;}public int getUserLimit(){return userLimit;}public void update(BigDecimal p,int rate,int users){monthlyPrice=p;apiRateLimit=rate;userLimit=users;}}
